// Obtener input del webhook o usar defaults para test manual
const triggerData = $('Webhook — Recibir solicitud de contenido').first()?.json?.body || {};
const products = $input.all().map(i => i.json);

const platform = triggerData.platform || 'instagram';
const tone = triggerData.tone || 'casual';
const requestedSku = triggerData.product_sku;

const product = requestedSku
  ? (products.find(p => p.sku === requestedSku) || products[0])
  : products[Math.floor(Math.random() * products.length)];

const precio = product.precio_unitario.toLocaleString('es-AR', { style: 'currency', currency: 'ARS' });

const templates = {
  instagram: {
    formal: `✨ Calidad artesanal en cada frasco.\n\n🫒 ${product.nombre}\nElaborado con ingredientes seleccionados de la región.\n\nVisitá nuestra tienda y pedí el tuyo.\n\n#GoldenHarvest #ProductosArtesanales #Gourmet #Argentina #Conservas`,
    casual: `¿Ya probaste nuestro ${product.nombre.split(' ').slice(0, 3).join(' ')}? 😍\n\nUn clásico que no podés dejar pasar. ¡Pedí el tuyo hoy!\n\n#GoldenHarvest #FoodLovers #Artesanal #ArgentinaFood`
  },
  whatsapp: {
    formal: `Estimado cliente,\n\nLe compartimos nuestra novedad destacada:\n\n*${product.nombre}*\nPrecio: ${precio} por unidad\n\nDisponible para pedidos mayoristas. ¿Le interesa recibir más información?\n\nAtentamente,\n_Equipo Golden Harvest S.A._`,
    casual: `¡Hola! 👋 ¿Viste lo que tenemos esta semana?\n\n*${product.nombre}* — ${precio} la unidad 🔥\n\n¿Hacemos un pedido? Escribinos y te damos todos los detalles 🛒`
  },
  facebook: {
    formal: `Golden Harvest presenta: ${product.nombre}. Tradición y calidad artesanal en cada producto. Consultá disponibilidad y precios mayoristas.`,
    casual: `¡Mirá lo que tenemos para vos! 🌟 ${product.nombre} — ideal para tu negocio o mesa gourmet. ¡Comentá si querés más info!`
  },
  linkedin: {
    formal: `Golden Harvest S.A. continúa expandiendo su línea de productos artesanales. Nuestro ${product.nombre} representa el compromiso con la calidad y la tradición argentina. Disponible para distribuidores y cadenas de retail. Contacte a nuestro equipo comercial.`,
    casual: `Orgullosos de presentar nuestro ${product.nombre}. Producto 100% argentino, elaborado artesanalmente. ¿Tu empresa trabaja con productos gourmet? ¡Conectemos!`
  }
};

const caption = templates[platform]?.[tone] || templates.instagram.casual;
const imagePrompt = `professional product photo of ${product.nombre}, artisanal food jar, golden harvest argentina brand, white clean background, food photography`;
const imageUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(imagePrompt)}?width=1080&height=1080&nologo=true`;

console.log(`\n=== CONTENIDO GENERADO ===`);
console.log(`Plataforma: ${platform} | Tono: ${tone}`);
console.log(`Producto: ${product.nombre} (${product.sku})`);
console.log(`Caption (${caption.length} chars):\n${caption}`);
console.log(`Imagen: ${imageUrl}`);

return [{ json: { product, platform, tone, caption, image_url: imageUrl, image_prompt: imagePrompt, status: 'listo_para_publicar' } }];

